print(sum(x * x for x in range(5)))
print(min(x - 3 for x in range(6)), max(x % 4 for x in range(10)))
print(sorted(x % 3 for x in range(7)))
print(list(x + 1 for x in range(3)))
print(set(x % 2 for x in range(5)))
print(dict((x, x * 2) for x in range(3)))
print(",".join(str(x) for x in range(4)))
print(" ".join(w.upper() for w in "a bc d".split()))
print(sum(1 for c in "banana" if c == "a"))
print(len(list(x for x in range(5) if x > 1)))
print(sum(len(w) for w in ["ab", "cde"]))
